message.content:
{
  "description": "The creature is a single quadrupedal equine shown in right-facing profile against a plain light background. It has a stocky donkey-like body with a brownish-gray shaggy coat that is lighter on the belly and muzzle, a short upright mane along the neck, large upright ears, and a thin tail with a dark tuft. Faint to moderate dark striping is visible across the torso, hindquarters, neck, and lower legs, and the animal stands on four slender legs ending in single hooves.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated equine head with a blunt muzzle, white-gray hair around the nostrils and mouth, a large dark nostril, a small closed mouth with whiskers on the lower lip and chin, a dark eye with a pale ring around it, and coarse brown fur with darker shading on the forehead and cheeks",
      "where": "at the front end of the neck, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two large, upright, pointed ears with rounded tips, brown on the outside, pale on the inner rim and dark brown-black inside the ear canal, with fine hair along the edges",
      "where": "on top of the head, one slightly in front of the other in profile view"
    },
    {
      "part": "mane",
      "looks_like": "short, stiff, upright brush-like mane made of dark brown to black spiky hairs with lighter tips, standing erect along the crest",
      "where": "along the dorsal midline of the neck from behind the ears to the withers"
    },
    {
      "part": "legs",
      "looks_like": "four slender equine legs with visible joints at shoulder/hip, knee/hock, and fetlock; covered in short hair that is brown-gray above and paler below, with dark horizontal striping on the lower portions; the two forelegs are nearly vertical and close together, the two hind legs are set slightly apart with the rear-most leg extended back",
      "where": "two forelegs under the chest and two hind legs under the rump, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "single solid hooves on each leg, dark gray-brown, rounded at the front and slightly angled, with a small tuft of hair above the hoof",
      "where": "at the bottom tip of each of the four legs"
    },
    {
      "part": "tail",
      "looks_like": "thin, narrow tail covered in short hair with a longer dark brown-black tuft of coarse hair at the tip, hanging straight down",
      "where": "extending from the rear of the rump at the back of the animal"
    },
    {
      "part": "markings",
      "looks_like": "dark brown to black stripes of varying width and intensity: a thin dark dorsal stripe along the spine, a vertical shoulder stripe, several faint vertical to diagonal stripes on the neck, torso and hindquarters, and multiple horizontal bands on the lower forelegs and hind legs; the stripes are most distinct on the hindquarters and lower legs and more faded on the mid-body",
      "where": "across the neck, shoulders, back, sides, rump, and all four lower legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "donkey",
    "zebra"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
